∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {mc : Breakdown.CertCell.ModeCharges} {e₁ e₂ : Breakdown.CertCell.TailBand.EntryCharges}
  {mm : ℕ} {ι : ℤ × ℤ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space} {p : ℝ × ℝ},
  e₁.stretchConst = e₂.stretchConst →
    e₁.curlCharge p ≤ e₂.curlCharge p →
      e₁.gradCharge p ≤ e₂.gradCharge p →
        e₁.velCharge p ≤ e₂.velCharge p →
          Breakdown.CertCell.TailBand.offModeDensity m P h w mc e₂ mm ι v G H p ≤
            Breakdown.CertCell.TailBand.offModeDensity m P h w mc e₁ mm ι v G H p

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {A : Breakdown.CertCell.Assembly.AssemblyEntry D R}
  {P : Breakdown.CertCell.Assembly.CouplingEntries D R}
  {states : (K : Fin D.mesh.count) → (Breakdown.CertCell.Assembly.CellVars D R K → ℂ) → Prop},
  Breakdown.CertCell.Assembly.PotentialConditions D R A P states →
    Breakdown.CertCell.Assembly.CellProfileRegular D →
      ∀ {K : Fin D.mesh.count} {q : Fin k → ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
        {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
        {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
        {g : ℝ → Breakdown.Space → Breakdown.Space} {κ : Fin k → ℝ} {F Pg : ℝ → Breakdown.Space → Breakdown.Space},
        Breakdown.CertCell.Assembly.IsCellTuple D K q v G H g κ F Pg →
          ∀ {ι : ℤ × ℤ} (hι : ι ∈ D.mesh.resolved K) (xb : Breakdown.CertCell.Assembly.CellVars D R K → ℂ)
            (cA sA vA : ℝ),
            Breakdown.CertCell.Assembly.Internal.Sharp.NullOn✝ (D.mesh.box K).rect fun p =>
              (D.mesh.box K).lineWeight p.1 *
                (2 *
                  Breakdown.CertCell.Assembly.Internal.Sharp.absorbCross✝ cA sA vA
                    (Breakdown.CertCell.Assembly.lowProfile D R K ⟨ι, hι⟩ xb p)
                    (Breakdown.CertCell.Assembly.tailProfile D R K ι v G p))

∀ {C : Type} {nE nM : ℕ} {w : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {wt : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space}
