              MeasureTheory.IntegrableOn
                (fun p => (D.mesh.box K).lineWeight p.1 * ‖Breakdown.CertCell.Assembly.tailProfile D R K ι v G p j‖ ^ 2)
                (D.mesh.box K).rect MeasureTheory.volume

