          (Breakdown.CertCell.Assembly.sesq12 ((P.potential K).couplingModel α p) X Y).re =
            (Breakdown.CertCell.Assembly.sesq12 ((P.potential K).couplingModel (-α) p) Y X).re

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
