        Breakdown.CertCell.Assembly.IsCellTuple D K q v G H g κ F Pg →
          ∀ (ι : ℤ × ℤ) (j : Fin 12),
            MeasureTheory.AEStronglyMeasurable (fun p => Breakdown.CertCell.Assembly.bandProfile D ι v G p j)
                (MeasureTheory.volume.restrict (D.mesh.box K).rect) ∧
              MeasureTheory.IntegrableOn
