                (D.mesh.box K).rect MeasureTheory.volume

∀ {k : ℕ} {Γ : Set Breakdown.Symmetry} {P : ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space}
  {b : Fin k → ℝ → Breakdown.Space → Breakdown.Space} {κ : Fin k → ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g F : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    (∃ γ ∈ Γ, (∀ (y : Breakdown.Space), γ.1 y = Breakdown.CertCell.flipPoint y) ∧ γ.2 = 0) →
      (∀ (σ : ℝ) (y : Breakdown.Space), W σ (Breakdown.CertCell.flipPoint y) = Breakdown.CertCell.flipPoint (W σ y)) →
        (∀ (i : Fin k),
            ∀ᵐ (z : ℝ × Breakdown.Space),
              b i z.1 (Breakdown.CertCell.flipPoint z.2) = Breakdown.CertCell.flipPoint (b i z.1 z.2)) →
          Breakdown.Cert.IsPeriodicField F →
            Breakdown.IsRightSide W b κ v G g F → Breakdown.IsRightSide W b κ v G g (Breakdown.CertCell.flipAverage F)

∀ {k : ℕ} {C : Type} {nE nM : ℕ} (D : Breakdown.CertCell.CellLayerData k C nE nM) {K : Fin D.mesh.count}
